export type SequenceMilestone =
  | "original_decision"
  | "correction"
  | "later_probe"
20→  | "outcome";

export const KEY_SEQUENCE_MILESTONES: readonly SequenceMilestone[] = [
  "original_decision",
  "correction",
  "later_probe",
