/**
 * Standing corrections currently targeting `role`, in the order they were
 * issued. Lifted corrections are omitted — they no longer target anyone.
 */
directivesFor(role: Role): StandingDirective[] {
  return this.standingDirectives
    .filter((directive) => !directive.lifted && directive.roles.includes(role))
    .map((directive) => this.toPublicDirective(directive));
}

/** Every standing correction currently in force, in issue order. */
activeDirectives(): StandingDirective[] {
  return this.standingDirectives
    .filter((directive) => !directive.lifted)
    .map((directive) => this.toPublicDirective(directive));
}

/**
 * Warming-shelf probe. `outcome` is `"pending"` only before the shelf
 * complication fires; the instant it does — even with an empty `decisions`
 * list — it reads `"scope_held"`, and moves to `"over_generalized"` only
 * once a false positive has been recorded. See CORRECTIONS_AND_PROBE_CONTRACT.md.
 */
probeReport(): ProbeReport {
  const decisions = this.probeDecisions.map((decision) => ({ ...decision }));
  const falsePositives = decisions.filter((decision) => decision.falsePositive).length;
  let outcome: ProbeReport["outcome"] = "pending";
  if (this.probeTriggeredAt !== undefined) {
    outcome = falsePositives > 0 ? "over_generalized" : "scope_held";
  }
  return { outcome, falsePositives, decisions };
}

